+                    <button type="button" class="button button-secondary" aria-label="Share image: ${image.title}">
+                      Share
+                    </button>
+                    <button
+                      type="button"
+                      class="button button-danger trigger"
+                      id="openDeleteDialog"
+                      aria-haspopup="dialog"
+                      aria-controls="deleteDialog"
+                    >
+                      Delete image
+                    </button>
+                  </div>
+                </div>
+              </section>
+
+              <aside class="card side-panel" aria-labelledby="details-heading">
+                <p class="side-label">Image details</p>
+                <h2 id="details-heading" class="side-heading">Ready for review</h2>
+                <p class="side-copy">
+                  Confirm final changes, share the asset, or remove it from your library.
+                </p>
