         padding: 0.75rem 1rem;
         border-radius: 999px;
         background: var(--surface-strong);
         color: var(--text);
         text-decoration: none;
         transform: translateY(-200%);
         transition: transform 0.2s ease;
         z-index: 20;
       }

       .skip-link:focus {
         transform: translateY(0);
       }

       .shell {
         width: min(1120px, calc(100% - 2rem));
         margin: 0 auto;
         padding: 1.5rem 0 3rem;
       }

       .topbar {
         display: flex;
