         border-radius: 16px;
         background: linear-gradient(135deg, #2563eb, #7c3aed);
         box-shadow: inset 0 1px 1px rgba(255, 255, 255, 0.35);
       }

       .library-link {
         color: var(--text-muted);
         text-decoration: none;
         font-weight: 600;
       }

       .library-link:hover {
         color: var(--text);
       }

       .page-grid {
