       .empty-state {
         display: flex;
         align-items: center;
         justify-content: center;
         min-height: 220px;
         padding: 2rem;
         border: 1px dashed rgba(23, 32, 51, 0.18);
         border-radius: 22px;
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.6), rgba(238, 243, 251, 0.9));
         text-align: center;
       }

       .empty-state[hidden] {
         display: none;
       }

       .empty-state strong {
         display: block;
         margin-bottom: 0.35rem;
         font-size: 1.1rem;
       }

       dialog {
         width: min(32rem, calc(100% - 1.5rem));
         padding: 0;
         border: none;
         border-radius: 24px;
         background: var(--surface-strong);
         color: inherit;
         box-shadow: 0 28px 90px rgba(15, 23, 42, 0.35);
       }

       dialog::backdrop {
