         background: var(--danger-soft);
         color: var(--danger);
         font-size: 1.4rem;
       }

       .dialog-title {
         margin: 0;
         font-size: 1.4rem;
         letter-spacing: -0.03em;
       }

       .dialog-copy {
         margin: 0.85rem 0 0;
       }

       .dialog-actions {
         display: flex;
         justify-content: flex-end;
         gap: 0.75rem;
         margin-top: 1.5rem;
         flex-wrap: wrap;
       }

       :focus-visible {
         outline: 3px solid #0f172a;
         outline-offset: 3px;
       }

       @media (max-width: 860px) {
         .page-grid {
           grid-template-columns: 1fr;
         }

         .preview-footer {
           align-items: flex-start;
         }
       }

       @media (max-width: 520px) {
         .shell {
           width: min(100% - 1rem, 1120px);
           padding-top: 1rem;
         }

         .topbar,
         .preview-footer,
         .dialog-actions,
         .detail-row {
           flex-direction: column;
           align-items: stretch;
         }

         .detail-row dd {
           text-align: left;
         }
       }

       @media (prefers-reduced-motion: reduce) {
         *,
         *::before,
         *::after {
           animation: none !important;
           transition: none !important;
           scroll-behavior: auto !important;
         }
       }

       @media (forced-colors: active) {
         .card,
         dialog,
         .button,
         .detail-row,
         .empty-state,
         .preview-media {
           border: 1px solid CanvasText;
           box-shadow: none;
         }

         .button-danger,
         .button-primary {
           background: ButtonFace;
           color: ButtonText;
         }
       }
     </style>
   </head>
   <body>
     <div id="app"></div>
     <script>
       const imageData = {
         title: "Golden Coastline",
         type: "Landscape photo",
         dimensions: "6144 x 3840 px",
         location: "Big Sur, California",
         dateAdded: "May 6, 2026",
         description: "High-resolution preview of a golden-hour coastline capture ready for editing or export.",
         alt: "Preview of a coastal landscape with cliffs, ocean, and warm sunset light.",
         src:
           "data:image/svg+xml;utf8," +
           encodeURIComponent(`
             <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 1000" role="img" aria-label="Golden coastline illustration">
               <defs>
                 <linearGradient id="sky" x1="0" y1="0" x2="0" y2="1">
                   <stop offset="0%" stop-color="#9fd2ff"/>
                   <stop offset="46%" stop-color="#ffd8aa"/>
                   <stop offset="100%" stop-color="#f3c38f"/>
                 </linearGradient>
                 <linearGradient id="sea" x1="0" y1="0" x2="1" y2="1">
                   <stop offset="0%" stop-color="#4f83cc"/>
                   <stop offset="100%" stop-color="#173a7a"/>
                 </linearGradient>
                 <linearGradient id="cliff" x1="0" y1="0" x2="1" y2="1">
                   <stop offset="0%" stop-color="#8a563d"/>
                   <stop offset="100%" stop-color="#5b3526"/>
                 </linearGradient>
               </defs>
               <rect width="1600" height="1000" fill="url(#sky)"/>
               <circle cx="1180" cy="250" r="96" fill="#fff5dc" opacity="0.8"/>
               <path d="M0 640 C220 610 300 670 520 630 C780 580 910 660 1160 625 C1320 602 1430 618 1600 580 V1000 H0 Z" fill="url(#sea)"/>
               <path d="M0 720 C90 650 180 535 350 500 C510 470 590 535 720 505 C830 480 940 385 1120 360 C1310 334 1440 412 1600 300 V1000 H0 Z" fill="url(#cliff)"/>
               <path d="M0 820 C180 760 330 802 500 760 C720 706 870 760 1030 716 C1230 660 1370 725 1600 650 V1000 H0 Z" fill="#341f19" opacity="0.6"/>
               <path d="M1120 650 C1200 620 1340 610 1480 635" stroke="#d7ebff" stroke-width="12" stroke-linecap="round" opacity="0.9"/>
             </svg>
           `),
       };

       const root = document.getElementById("app");

       function App() {
         return `
           <a class="skip-link" href="#maincontent">Skip to main content</a>
           <div class="shell">
             ${Header()}
             ${ImagePreviewPage(imageData)}
           </div>
           ${ConfirmDeleteDialog()}
         `;
       }

       function Header() {
         return `
           <header class="topbar">
             <div class="brand" aria-label="PixelKeep">
               <span class="brand-badge" aria-hidden="true"></span>
               <span>PixelKeep</span>
             </div>
             <nav aria-label="Primary">
               <a class="library-link" href="#maincontent">Library</a>
             </nav>
           </header>
         `;
       }

       function ImagePreviewPage(image) {
         return `
           <main id="maincontent" tabindex="-1">
             <div class="page-grid">
               <section class="card preview-card" aria-labelledby="image-title">
                 <div id="previewMedia" class="preview-media">
                   <img src="${image.src}" alt="${image.alt}" />
                 </div>
                 <div id="emptyState" class="empty-state" hidden>
                   <div>
                     <strong>Image removed from your library</strong>
                     <span class="side-copy">This preview is no longer available.</span>
                   </div>
                 </div>
                 <div class="preview-footer">
                   <div>
                     <p class="meta-eyebrow">${image.type}</p>
                     <h1 id="image-title" class="meta-title">${image.title}</h1>
                     <p class="meta-copy">${image.description}</p>
                   </div>
                   <div class="actions">
                     <button type="button" class="button button-secondary" aria-label="Share image: ${image.title}">
                       Share
                     </button>
                     <button
                       type="button"
                       class="button button-danger trigger"
                       id="openDeleteDialog"
                       aria-haspopup="dialog"
                       aria-controls="deleteDialog"
                     >
                       Delete image
                     </button>
                   </div>
                 </div>
               </section>

               <aside class="card side-panel" aria-labelledby="details-heading">
                 <p class="side-label">Image details</p>
                 <h2 id="details-heading" class="side-heading">Ready for review</h2>
                 <p class="side-copy">
                   Confirm final changes, share the asset, or remove it from your library.
                 </p>
                 <dl class="detail-list">
                   <div class="detail-row">
                     <dt>Dimensions</dt>
                     <dd>${image.dimensions}</dd>
                   </div>
                   <div class="detail-row">
                     <dt>Location</dt>
                     <dd>${image.location}</dd>
                   </div>
                   <div class="detail-row">
                     <dt>Date added</dt>
                     <dd>${image.dateAdded}</dd>
                   </div>
                 </dl>
                 <p id="statusMessage" class="status" aria-live="polite"></p>
               </aside>
             </div>
           </main>
         `;
       }

       function ConfirmDeleteDialog() {
         return `
           <dialog id="deleteDialog" aria-labelledby="deleteDialogTitle" aria-describedby="deleteDialogDescription">
             <form method="dialog" class="dialog-card">
               <div class="dialog-icon" aria-hidden="true">!</div>
               <h2 id="deleteDialogTitle" class="dialog-title">Delete this image from your library?</h2>
               <p id="deleteDialogDescription" class="dialog-copy">
                 This removes <strong>${imageData.title}</strong> from your library and clears the current preview.
               </p>
               <div class="dialog-actions">
                 <button type="submit" class="button button-secondary" id="cancelDeleteButton" value="cancel">
                   Cancel
                 </button>
                 <button type="submit" class="button button-danger" value="delete">
                   Delete image
                 </button>
               </div>
             </form>
           </dialog>
         `;
       }

       root.innerHTML = App();

       const dialog = document.getElementById("deleteDialog");
       const mainContent = document.getElementById("maincontent");
       const trigger = document.getElementById("openDeleteDialog");
       const cancelButton = document.getElementById("cancelDeleteButton");
       const previewMedia = document.getElementById("previewMedia");
       const emptyState = document.getElementById("emptyState");
       const statusMessage = document.getElementById("statusMessage");

       trigger.addEventListener("click", () => {
         dialog.showModal();
         window.requestAnimationFrame(() => cancelButton.focus());
       });

       dialog.addEventListener("click", (event) => {
         const bounds = dialog.getBoundingClientRect();
         const clickedBackdrop =
           event.clientX < bounds.left ||
           event.clientX > bounds.right ||
           event.clientY < bounds.top ||
           event.clientY > bounds.bottom;

         if (clickedBackdrop) {
           dialog.close("cancel");
         }
       });

       dialog.addEventListener("close", () => {
         if (dialog.returnValue !== "delete") {
           return;
         }

         previewMedia.hidden = true;
         emptyState.hidden = false;
         trigger.disabled = true;
         trigger.textContent = "Image deleted";
         statusMessage.textContent = "Image deleted from your library.";
         window.requestAnimationFrame(() => mainContent.focus());
       });
     </script>
   </body>
 </html>

